NEWLINE = chr(10)
SEVERITY_AR = {"high": "خطير", "medium": "متوسط", "low": "بسيط"}


def _note(number, issue):
    """One of an old check's notes as plain lines, the way the chat's answers are written."""
    head = f"{number}. [{SEVERITY_AR.get(issue.get('severity'), 'متوسط')}]"
    if issue.get("location"):
        head += f" {issue['location']}"
    lines = [head]
    if issue.get("source_excerpt"):
        lines.append(f"الأصل: «{issue['source_excerpt']}»")
    if issue.get("translation_excerpt"):
        lines.append(f"الترجمة: «{issue['translation_excerpt']}»")
    what = issue.get("issue_ar") or issue.get("issue_en") or issue.get("issue")
    if what:
        lines.append(f"الغلط: {what}")
    if issue.get("correct_meaning_ar"):
        lines.append(f"المعنى الصحيح: {issue['correct_meaning_ar']}")
    return NEWLINE.join(lines)


def convert_old_checks(apps, schema_editor):
    """Every review the leader already has becomes a session of its own: what he sent (the names) and what the AI said back."""
    Check = apps.get_model("dashboard", "DocumentCheck")
    Session = apps.get_model("dashboard", "AIReviewSession")
    Message = apps.get_model("dashboard", "AIReviewMessage")
    for check in Check.objects.exclude(created_by=None).order_by("id"):
        targets, sources = check.target_names or [], check.source_names or []
        title = (targets[0] if targets else "") or (sources[0] if sources else "") or "مراجعة"
        session = Session.objects.create(owner_id=check.created_by_id, title=title[:120])
        asked = ["راجع الترجمة على الأصل."]
        if sources:
            asked.append("الأصل: " + " · ".join(sources))
        if targets:
            asked.append("الترجمة: " + " · ".join(targets))
        if check.source_lang or check.target_lang:
            asked.append(f"من {check.source_lang or '?'} إلى {check.target_lang or '?'}")
        if check.instructions:
            asked.append(check.instructions)
        question = Message.objects.create(session=session, role="user", body=NEWLINE.join(asked), status="done")
        if check.status == "error" or check.status == "running":
            answer = Message.objects.create(session=session, role="assistant", status="error", error_message="The check did not finish.")
        else:
            parts = [check.summary] if check.summary else []
            parts += [_note(number, one) for number, one in enumerate(check.issues or [], 1) if isinstance(one, dict)]
            if not check.issues:
                parts.append("مفيش أخطاء واضحة. المراجعة البشرية لسه مطلوبة.")
            answer = Message.objects.create(session=session, role="assistant", body=(NEWLINE * 2).join(parts), status="done")
        moment = check.finished_at or check.created_at
        Message.objects.filter(pk=question.pk).update(created_at=check.created_at)
        Message.objects.filter(pk=answer.pk).update(created_at=moment)
        Session.objects.filter(pk=session.pk).update(created_at=check.created_at, updated_at=moment)


